(() => {
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const slug=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');let byPath=new Map(),paths=new Map(),all=[],current=null,quantity=1;
function configure(products){all=products.filter(p=>!p.archived);byPath=new Map();paths=new Map();for(const p of all){const root=p.game==='accounts'?'/contas/':p.game==='giftcards'?'/gift-cards/':'/robux/';let path=root+(slug(p.name)||'produto-'+p.id);if(byPath.has(path))path+='-'+p.game;if(byPath.has(path))path+='-'+p.id;paths.set(p.id,path);byPath.set(path,p)}}
const url=p=>paths.get(p.id)||'/loja';const resolve=path=>byPath.get(path);
const game=p=>({bloxfruits:'Blox Fruits',brainrot:'Steal a Brainrot',mm2:'MM2',accounts:'Contas Blox Fruits',giftcards:'Gift Cards'})[p.game]||'Roblox';
const back=p=>p.game==='accounts'?'/contas':p.game==='giftcards'?'/gift-cards':'/loja/'+p.game;
const image=p=>p.image||window.originalMedia?.products?.[p.id]||'/assets/'+p.art+'.svg';
const maximum=p=>p.game==='accounts'?Math.min(99,p.stock||1):99;
const humanClips=[{name:'M1 Combo',src:'https://static.wikia.nocookie.net/roblox-blox-piece/images/2/2a/Godhumanm1s.gif/revision/latest?cb=20251229120647'},{name:'Sixth Realm Gun',src:'https://static.wikia.nocookie.net/roblox-blox-piece/images/5/54/Sixth_Realm_Gun_charge.gif/revision/latest?cb=20260422084827'}];
function factArt(text){if(/Level/i.test(text))return '<div class="pdp-level-number">'+(/2800 MAX/.test(text)?'2800':'1500<span>–2800</span>')+'<small>'+(/MAX/.test(text)?'MAX':'LEVEL')+'</small></div>';let src=/God Human/i.test(text)?window.originalMedia?.human:/Cursed Dual/i.test(text)?window.originalMedia?.cdk:/Kitsune/i.test(text)?window.originalMedia?.products?.[9]:null;return src?'<img src="'+src+'" alt="" loading="lazy">':'<div class="pdp-mystery" aria-hidden="true">?</div>'}
function fact(text,possible){return '<article class="pdp-inventory-card '+(/Level/.test(text)?'is-level':'is-mythic')+'"><small>'+(possible?'POSSIBILIDADE':'100% GARANTIDO')+'</small><div class="pdp-inventory-art">'+factArt(text)+'</div><strong>'+esc(text)+'</strong>'+(possible?'<span class="pdp-chance">'+possible+'% de chance · não garantido</span>':'')+'</article>'}
function humanResource(possible){return '<article class="pdp-resource"><div class="pdp-resource-gallery" data-resource-gallery><div class="pdp-resource-screen"><img data-resource-main src="'+humanClips[0].src+'" alt="M1 Combo de God Human" loading="lazy" referrerpolicy="no-referrer"><span class="pdp-clip-label" data-resource-label>M1 Combo</span></div><div class="pdp-resource-thumbs">'+humanClips.map((c,i)=>'<button data-resource-clip="'+i+'" aria-label="Ver '+c.name+' de God Human" aria-pressed="'+(i===0)+'"><img src="'+c.src+'" alt="" loading="lazy" referrerpolicy="no-referrer"></button>').join('')+'</div></div><div class="pdp-resource-copy"><span class="eyebrow">ESTILO DE LUTA <b>'+(possible?' · '+possible+'% DE CHANCE':' · ✓ INCLUÍDO')+'</b></span><h3><img src="'+window.originalMedia.human+'" alt="">God Human</h3><p>Mobilidade e controle para montar seus combos no PvP.</p><ul><li>Alta mobilidade</li><li>Dano elevado</li><li>Combos de ataques</li><li>Habilidades de controle</li></ul>'+(possible?'<p class="pdp-account-note">Este recurso é uma possibilidade, não um item garantido.</p>':'')+'</div></article>'}
function accountContents(p){const d=p.accountDetails||{guaranteed:[]};const human=d.guaranteed.some(s=>s.includes('God Human')),possible=d.possible?.find(s=>s.name==='God Human');return '<section class="pdp-account-content" aria-labelledby="pdp-details-title"><div class="pdp-inventory-heading"><div><h2 id="pdp-details-title">Conteúdo da conta</h2><p>Confira os itens incluídos e os recursos que podem variar.</p></div><span>'+d.guaranteed.length+' GARANTIDOS</span></div><span id="pdp-receive" class="pdp-account-receive">1 × '+esc(p.name)+'</span><h3 class="pdp-guaranteed-title">GARANTIDOS</h3><p class="pdp-inventory-hint">Recursos incluídos conforme o anúncio.</p><div class="pdp-inventory-grid">'+(d.guaranteed.map(s=>fact(s)).join('')||'<p>O anúncio não informa recursos garantidos.</p>')+'</div>'+(d.possible?.length?'<h3 class="pdp-guaranteed-title is-possible-title">POSSIBILIDADES</h3><div class="pdp-inventory-grid">'+d.possible.map(s=>fact(s.name,s.chance)).join('')+'</div>':'')+'<p class="pdp-account-footnote">ⓘ Outros itens podem estar presentes por conta da evolução do personagem.</p><h3 class="pdp-account-label">INFORMAÇÕES DA CONTA</h3><dl class="pdp-account-info"><div><dt>Dinheiro no jogo</dt><dd>'+esc(d.money)+'</dd></div>'+(d.warranty?'<div><dt>Garantia informada no anúncio original</dt><dd>'+esc(d.warranty)+'</dd></div>':'')+'</dl>'+(d.note?'<p class="pdp-account-note">'+esc(d.note)+'</p>':'')+((human||possible)?'<h3 class="pdp-account-label">RECURSOS ESPECIAIS</h3>'+humanResource(possible?.chance):'')+(d.guaranteed.some(s=>s.includes('Cursed Dual Katana'))?'<article class="pdp-resource pdp-resource-sword"><img src="'+window.originalMedia.cdk+'" alt="Cursed Dual Katana" loading="lazy"><div class="pdp-resource-copy"><span class="eyebrow">ESPADA · ✓ INCLUÍDA</span><h3>Cursed Dual Katana</h3><p>Golpes rápidos, alcance e combinações de ataques.</p><ul><li>Ataques à distância</li><li>Alto dano</li><li>Golpes rápidos</li><li>Combinações de ataques</li></ul></div></article>':'')+'</section>'}
function productShowcase(p){if(p.game==='accounts')return '';return '<section class="pdp-showcase"><div class="pdp-showcase-media">'+(p.game==='bloxfruits'?'<video autoplay muted loop playsinline preload="metadata" poster="'+window.originalMedia.bloxPoster+'" aria-label="Visão geral de Blox Fruits"><source src="'+window.originalMedia.bloxVideo+'" type="video/webm"><source src="'+window.originalMedia.bloxMp4+'" type="video/mp4"></video>':'<img src="'+image(p)+'" alt="'+esc(p.name)+'" loading="lazy">')+'</div><div><span class="eyebrow">'+esc(game(p))+'</span><h2>'+esc(p.name)+'</h2><p>'+(p.game==='giftcards'?'Cartão com saldo de R$ '+esc(p.value)+'. Confira o valor facial e o preço do pedido antes de continuar.':p.game==='bloxfruits'?'Visão geral do jogo. O item selecionado e a quantidade estão descritos no resumo do pedido.':'Confira a imagem do item, sua categoria e a quantidade escolhida.')+'</p><div class="pdp-showcase-tags"><span>'+esc(p.category)+'</span><span>Revisão antes de confirmar</span></div></div></section>'}
function page(p){current=p;quantity=1;const max=maximum(p),presets=[1,5,10,20].filter(q=>q<=max),features=p.features||[];return `<div class="pdp-page"><div class="wrap"><div class="breadcrumb pdp-breadcrumb"><a href="/">⌂ Início</a> › <a href="${back(p)}">${esc(game(p))}</a> › <span>${esc(p.name)}</span></div><section class="pdp-main" aria-label="Comprar ${esc(p.name)}"><div class="pdp-visual"><img src="${image(p)}" alt="${esc(p.name)}" fetchpriority="high"><span>${esc(p.category)}</span></div><div class="pdp-config"><div class="pdp-chips"><span><img src="/assets/original/40a6e56dd9fe8c72.svg" alt="">Roblox</span><a href="${back(p)}">${esc(game(p))} ↗</a></div><h1>${esc(p.name)}</h1><p class="pdp-description">${p.game==='accounts'?esc(p.accountDetails?.subtitle||'Confira os recursos desta conta antes de escolher.'):p.game==='giftcards'?'Escolha seu cartão e confira o saldo e o valor do pedido.':'Escolha a quantidade e confira os detalhes do item para seu jogo.'}</p><a class="pdp-review-link" href="#pdp-reviews">★★★★★ <span>Avaliações da loja original</span></a><div class="pdp-price-box"><small>VOCÊ PAGA</small><strong id="pdp-total">${money(p.price)}</strong><span>${esc(p.name)}</span><small id="pdp-unit">${money(p.price)} por unidade</small></div><label class="pdp-qty-label" for="pdp-quantity">Quantidade</label><div class="pdp-quantity"><button data-pdp-step="-1" aria-label="Diminuir quantidade">−</button><input id="pdp-quantity" type="number" min="1" max="${max}" step="1" value="1" inputmode="numeric" aria-label="Quantidade"><button data-pdp-step="1" aria-label="Aumentar quantidade">+</button></div><div class="pdp-presets">${presets.map(q=>`<button data-pdp-qty="${q}" aria-pressed="${q===1}">${q}</button>`).join('')}</div><div class="pdp-gold-seal" aria-label="Informações da compra"><div><span class="pdp-seal-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3 5 6v6c0 4 7 8 7 8s7-4 7-8V6Z"/><path d="m9 11 2 2 4-4"/></svg></span><span><b>COMPRA SEGURA</b><small>Sem solicitar sua senha</small></span></div><div><span class="pdp-seal-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m13 2-9 12h7l-1 8 10-13h-7Z"/></svg></span><span><b>PEDIDO REVISADO</b><small>Confira antes de confirmar</small></span></div><div><span class="pdp-seal-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/></svg></span><span><b>PERFIL ROBLOX</b><small>Confira seu usuário e avatar</small></span></div></div><button class="button pdp-buy" data-pdp-buy>COMPRAR AGORA →</button><button class="pdp-add" data-pdp-add><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 3h2l3 13h11l2-9H6"/><circle cx="10" cy="21" r="1"/><circle cx="18" cy="21" r="1"/></svg>Adicionar ao carrinho</button><p class="pdp-demo">Compra demonstrativa · sem cobrança ou entrega real</p></div></section>${p.game==='accounts'?accountContents(p):`<section class="pdp-details" aria-labelledby="pdp-details-title"><div class="pdp-details-head"><span class="eyebrow">DETALHES DO ITEM</span><h2 id="pdp-details-title">Tudo sobre seu pedido</h2><p>Confira o produto e o que está selecionado.</p></div><div class="pdp-detail-card"><h3>${esc(p.name)}</h3><small>${esc(p.category)} · ${esc(game(p))}</small><span class="eyebrow">VOCÊ RECEBE</span><ul><li id="pdp-receive">1 × ${esc(p.name)}</li>${features.map(f=>`<li>${esc(f)}</li>`).join('')}${p.game==='giftcards'?`<li>Saldo facial do cartão: R$ ${p.value}</li>`:''}</ul><details><summary>MAIS DETALHES</summary><p>O pedido corresponde ao item, à quantidade e ao preço mostrados nesta página. ${p.illustrative?'A imagem deste item é uma ilustração alternativa. ':''}Confira os dados antes de continuar.</p></details><details><summary>COMO FUNCIONA A ENTREGA</summary><p>Na compra, informe o e-mail e o usuário Roblox e revise seu pedido. Esta versão registra uma demonstração local; não realiza pagamentos, emite códigos ou entrega itens.</p></details></div></section>`}${productShowcase(p)}</div><div id="pdp-reviews">${window.reviewWall?.page()||''}</div><section class="wrap faq pdp-faq"><h2>Dúvidas antes de comprar?</h2>${[['Preciso informar minha senha?','Não. O formulário pede somente e-mail e usuário Roblox, com consulta opcional ao perfil público.'],['Posso alterar a quantidade?','Sim. Use os botões, o campo de quantidade ou os atalhos antes de adicionar o produto.'],['Como reviso meu pedido?','Clique em Comprar agora ou abra o carrinho. Você poderá informar os dados, revisar os itens e confirmar a demonstração.']].map(([q,a])=>`<details><summary>${q}</summary><div class="faq-answer"><p>${a}</p></div></details>`).join('')}</section><section class="wrap pdp-related"><div><span class="eyebrow">CONTINUE EXPLORANDO</span><h2>Mais opções para você</h2></div><div class="pdp-related-grid">${all.filter(r=>r.game===p.game&&r.id!==p.id).slice(0,4).map(r=>`<a href="${url(r)}"><img src="${image(r)}" alt="${esc(r.name)}" loading="lazy"><h3>${esc(r.name)}</h3><strong>${money(r.price)}</strong><span>VER PRODUTO →</span></a>`).join('')}</div></section></div>`}
function sync(){if(!current||!document.querySelector('#pdp-quantity'))return;document.querySelector('#pdp-quantity').value=quantity;document.querySelector('#pdp-total').textContent=money(Math.round(current.price*100)*quantity/100);document.querySelector('#pdp-receive').textContent=quantity+' × '+current.name;document.querySelectorAll('[data-pdp-qty]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.pdpQty)===quantity)))}
function valid(){const input=document.querySelector('#pdp-quantity');if(!input||!input.reportValidity())return false;quantity=Number(input.value);return Number.isInteger(quantity)&&quantity>=1&&quantity<=maximum(current)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!document.querySelector('.pdp-page'))return;if(b.hasAttribute('data-pdp-step')){const input=document.querySelector('#pdp-quantity');quantity=Math.min(maximum(current),Math.max(1,(Number(input.value)||1)+Number(b.dataset.pdpStep)));sync()}if(b.hasAttribute('data-pdp-qty')){quantity=Number(b.dataset.pdpQty);sync()}if(b.hasAttribute('data-pdp-add')||b.hasAttribute('data-pdp-buy')){if(!valid())return;if(!window.lojaCart.addProduct({id:current.id,qty:quantity}))return;if(b.hasAttribute('data-pdp-buy'))window.lojaCart.checkout()}});
document.addEventListener('input',e=>{if(e.target.id==='pdp-quantity'&&e.target.checkValidity()){quantity=Number(e.target.value);document.querySelector('#pdp-total').textContent=money(Math.round(current.price*100)*quantity/100);document.querySelector('#pdp-receive').textContent=quantity+' × '+current.name;document.querySelectorAll('[data-pdp-qty]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.pdpQty)===quantity)))}});
let galleryTimer=null,observer=null;function mount(){clearInterval(galleryTimer);observer?.disconnect();const root=document.querySelector('.pdp-page');if(!root)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;root.querySelectorAll('.pdp-account-content,.pdp-detail-card,.pdp-showcase,.pdp-resource,.pdp-related-grid>a').forEach(el=>{if(reduce||!('IntersectionObserver' in window))return;el.classList.add('pdp-reveal');});if(!reduce&&'IntersectionObserver' in window){observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.08});root.querySelectorAll('.pdp-reveal').forEach(el=>observer.observe(el))}const galleries=[...root.querySelectorAll('[data-resource-gallery]')];if(!reduce&&galleries.length)galleryTimer=setInterval(()=>{if(document.hidden)return;galleries.forEach(g=>{if(!g.isConnected)return;const buttons=[...g.querySelectorAll('[data-resource-clip]')],i=buttons.findIndex(b=>b.getAttribute('aria-pressed')==='true');selectClip(g,(i+1)%buttons.length)})},6500);if(reduce)root.querySelectorAll('[data-resource-gallery]').forEach(g=>{g.querySelectorAll('img').forEach(img=>img.src=window.originalMedia.human);g.querySelector('.pdp-resource-thumbs').hidden=true;g.querySelector('[data-resource-label]').textContent='God Human'});if(reduce)root.querySelectorAll('video').forEach(v=>{v.pause();v.removeAttribute('autoplay')})}
function selectClip(g,index){const c=humanClips[index];if(!c)return;const img=g.querySelector('[data-resource-main]');img.src=c.src;img.alt=c.name+' de God Human';g.querySelector('[data-resource-label]').textContent=c.name;g.querySelectorAll('[data-resource-clip]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.resourceClip)===index)))}
document.addEventListener('error',e=>{const img=e.target;if(img.matches?.('[data-resource-gallery] img')&&!img.dataset.fallback){img.dataset.fallback='true';img.src=window.originalMedia.human;const label=img.closest('[data-resource-gallery]')?.querySelector('[data-resource-label]');if(label)label.textContent='Demonstração indisponível no servidor de origem'}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-resource-clip]');if(b)selectClip(b.closest('[data-resource-gallery]'),Number(b.dataset.resourceClip))});
window.productPages={configure,url,resolve,page,mount};
})();
